INSERT INTO about (image, title, description, seo_description, seo_title, language)
SELECT image, 'MSc. Dt. Mehmet Taş کیست؟',
'<p>دندان‌پزشک Mehmet Taş در سال ۱۹۸۶ در البستان استان کهرمان‌مرعش زاده شد. دورهٔ ابتدایی، راهنمایی و دبیرستان را در مرسین به پایان رساند. در سال ۲۰۰۴ وارد دانشکدهٔ دندان‌پزشکی دانشگاه استانبول شد و در سال ۲۰۰۹ از همان دانشکده دانش‌آموخته گردید. در سال ۲۰۱۰ خدمت سربازی خود را در توکات با درجهٔ ستوان‌دومی به پایان رساند.</p>
<p>پس از دانش‌آموختگی نزدیک دو سال در بیمارستان خصوصی Tem به‌عنوان دندان‌پزشک کار کرد. او از شرکای بنیان‌گذار پلی‌کلینیک خصوصی سلامت دهان و دندان Denttek است که از سال ۲۰۱۲ فعال است. در سال ۲۰۲۰ دورهٔ کارشناسی ارشد را در بخش جراحی دهان و ایمپلنتولوژی دانشگاه UniCamillus در ایتالیا به پایان رساند.</p>
<p>او عضو انجمن آکادمی دندان‌پزشکی زیبایی و انجمن OSSEDER است. بیشتر در زمینه‌های جراحی ایمپلنت، دندان‌پزشکی زیبایی و طراحی لبخند و کاربردهای بوتاکس عضلهٔ ماستر کار می‌کند. به انگلیسی مسلط است. به عکاسی دندانی علاقه دارد؛ متأهل و پدر یک فرزند است.</p>
<h2>تحصیلات و پیشینهٔ حرفه‌ای</h2>
<table>
<thead><tr><th>سال</th><th>مرحله</th></tr></thead>
<tbody>
<tr><td>۲۰۰۴–۲۰۰۹</td><td>دانشکدهٔ دندان‌پزشکی دانشگاه استانبول — تحصیل و دانش‌آموختگی</td></tr>
<tr><td>۲۰۱۰</td><td>خدمت سربازی (توکات، ستوان‌دوم)</td></tr>
<tr><td>۲۰۱۰–۲۰۱۲</td><td>بیمارستان خصوصی Tem — دندان‌پزشک</td></tr>
<tr><td>۲۰۱۲</td><td>پلی‌کلینیک خصوصی سلامت دهان و دندان Denttek — شریک بنیان‌گذار</td></tr>
<tr><td>۲۰۲۰</td><td>دانشگاه UniCamillus (ایتالیا) — کارشناسی ارشد جراحی دهان و ایمپلنتولوژی</td></tr>
</tbody>
</table>
<h2>عضویت‌های حرفه‌ای و حوزه‌های علاقه</h2>
<ul>
<li>عضویت انجمن آکادمی دندان‌پزشکی زیبایی</li>
<li>عضویت OSSEDER (انجمن اسئواینتگریشن)</li>
<li>جراحی ایمپلنت و برنامه‌ریزی جراحی پیشرفته</li>
<li>دندان‌پزشکی زیبایی و طراحی لبخند</li>
<li>بوتاکس عضلهٔ ماستر — کاربردهای عضلهٔ جونده در فشردن و سایش دندان</li>
<li>عکاسی دندانی و مستندسازی موارد بالینی</li>
</ul>
<h2>رویکرد بالینی</h2>
<p>در دندان‌پزشکی یک راه‌حل واحد برای همه درست نیست. برنامه در دو نفری که با یک شکایت می‌آیند می‌تواند متفاوت باشد؛ زیرا بافت سالم باقی‌ماندهٔ دندان، پشتیبانی لثه و استخوان، رابطهٔ اکلوژن، وضعیت عمومی سلامت و عادت‌های مراقبت روزانه از فردی به فرد دیگر تغییر می‌کند.</p>
<p>از این رو تصمیم درمان با ارزیابی هم‌زمان شنیدن شکایت، سابقهٔ پزشکی و دندانی، معاینهٔ بالینی و تنها تصویربرداری‌ای که لازم دیده می‌شود گرفته می‌گردد. هدف هر گزینهٔ قابل اجرا، سود و خطرهای مهم آن، گزینه‌های جایگزین و پیامدهای احتمالی درمان‌نشدن به‌صورت قابل فهم گفت‌وگو می‌شود. رضایت آگاهانه تنها یک امضا نیست؛ روندی از آگاهی‌رسانی روشن و امکان پرسیدن است.</p>
<p>در درمان‌های جامع اقدام‌ها به مراحل تقسیم می‌شوند: نخست کنترل وضعیت اورژانسی و عفونت، سپس متوقف‌کردن بیماری و سلامت پایهٔ لثه، پس از آن مراحل ترمیمی، جراحی یا پروتتیک قطعی و در پایان نظم مراقبت و معاینه. برای جزئیات روند به صفحهٔ <a href="/fa/tedavi-plani-ve-surec/">برنامهٔ درمان و روند آن</a> و برای آنچه در نخستین معاینه ارزیابی می‌شود به صفحهٔ <a href="/fa/ilk-dis-muayenesi-tedavi-planlamasi/">نخستین معاینهٔ دندان و برنامه‌ریزی درمان</a> نگاه کنید.</p>
<h2>کادر دندان‌پزشکان ما</h2>
<p>در کلینیک ما دندان‌پزشکانی در زمینه‌های ایمپلنتولوژی و جراحی دهان، اندودنتیکس، دندان‌پزشکی کودکان، ارتودنسی و درمان ترمیمی و پروتز کار می‌کنند. همهٔ درمان‌های حوزهٔ دندان‌پزشکی در کلینیک ما انجام می‌شوند. برای دیدن کامل کادر دندان‌پزشکان ما: <a href="https://denttek.com.tr/hekimlerimiz/" target="_blank" rel="noopener">Özel Denttek — دندان‌پزشکان ما</a></p>
<h2>پرسش‌های پرتکرار</h2>
<p><strong>MSc. Dt. Mehmet Taş در چه زمینه‌هایی کار می‌کند؟</strong><br>بیشتر در زمینه‌های جراحی ایمپلنت، جراحی دهان و دندان‌پزشکی زیبایی کار می‌کند. اقدام‌های حوزه‌های اندودنتیکس، دندان‌پزشکی کودکان، ارتودنسی و درمان ترمیمی و پروتز همراه با دندان‌پزشکان مربوط در کلینیک پیش برده می‌شوند.</p>
<p><strong>کارشناسی ارشد در چه رشته‌ای است؟</strong><br>در دانشگاه UniCamillus ایتالیا در رشتهٔ جراحی دهان و ایمپلنتولوژی به پایان رسیده است (۲۰۲۰).</p>
<p><strong>آیا بوتاکس عضلهٔ ماستر در گسترهٔ دندان‌پزشکی است؟</strong><br>بله. در کسانی که به‌دلیل فشردن و سایش دندان (بروکسیسم) عضلهٔ جونده‌شان بیش از حد کار می‌کند و بزرگ می‌شود، کاربرد سم بوتولینوم گزینه‌ای درمانی است که به ناحیهٔ فک و صورت می‌پردازد. تصمیم با در نظر گرفتن هم‌زمان ارزیابی اکلوژن، معاینهٔ عضله و مفصل و یافته‌های سایش گرفته می‌شود و بیشتر اوقات همراه با گزینه‌هایی مانند نایت‌گارد ارزیابی می‌گردد.</p>
<p><strong>آیا می‌توانم برای نظر دوم مراجعه کنم؟</strong><br>بله. گرفتن نظر دوم حق بیمار است. همراه‌آوردن رادیوگرافی، گزارش و ثبت‌های درمان موجود شما ارزیابی را آسان می‌کند.</p>
<p><strong>آیا گفت‌وگو به انگلیسی ممکن است؟</strong><br>بله، دندان‌پزشک به انگلیسی مسلط است.</p>
<p><strong>ثبت‌های درمان من چگونه نگهداری می‌شوند؟</strong><br>اطلاعاتی که در روند معاینه، تصویربرداری و درمان به دست می‌آید دادهٔ شخصی با ماهیت ویژه است. اینکه با چه هدفی پردازش می‌شود و چه حقوقی دارید در <a href="/fa/sayfa/kvkk-aydinlatma-metni">متن روشنگری حفاظت از داده‌های شخصی</a> توضیح داده شده است.</p>
<h2>ارزیابی منطقه‌ای</h2>
<p>در کلینیک ما در محل اتصال بیلیک‌دوزو/اسن‌یورت، برنامهٔ درمان با ارزیابی هم‌زمان معاینهٔ بالینی، تصویربرداری لازم و انتظارهای بیمار تدوین و با او در میان گذاشته می‌شود.</p>
<p><a href="/fa/tedaviler">سرفصل‌های درمان</a> &middot; <a href="/fa/implant/">درمان ایمپلنت</a> &middot; <a href="/fa/estetik/">دندان‌پزشکی زیبایی</a> &middot; <a href="/fa/iletisim">نوبت و تماس</a></p>',
'دربارهٔ تحصیلات دکتر Mehmet Taş، دورهٔ کارشناسی ارشد جراحی دهان و ایمپلنتولوژی، تجربهٔ بالینی و رویکرد درمانی او اطلاع یابید.',
'MSc. Dt. Mehmet Taş کیست؟ | تحصیلات و رویکرد بالینی',
'FA' FROM about WHERE language = 'TR';

INSERT INTO pages_description (page_id, title, description, seo_description, seo_title, language)
SELECT id, 'متن روشنگری حفاظت از داده‌های شخصی',
'<p>این متن از سوی Dt. Mehmet Taş به‌عنوان مسئول داده و بر پایهٔ قانون شمارهٔ ۶۶۹۸ ترکیه دربارهٔ حفاظت از داده‌های شخصی («KVKK») تهیه شده و به پردازش داده‌های شخصی بازدیدکنندگانی مربوط است که از فرم تماس و نوبت‌گیری وب‌سایت dtmehmettas.com.tr بهره می‌برند.</p>
<h2>مسئول داده</h2>
<p>Dt. Mehmet Taş — Cumhuriyet Mah. Nazım Hikmet Blv. No: 89/2, Esenyurt / İstanbul. ایمیل: info@dtmehmettas.com.tr، تلفن: +90 543 558 85 19.</p>
<h2>داده‌های شخصی پردازش‌شده</h2>
<p>از راه فرم تماس تنها نام و نام خانوادگی، شمارهٔ تلفن، نشانی ایمیل (اختیاری) و اطلاعاتی که در بخش پیام می‌نویسید پردازش می‌شود. از راه این فرم دادهٔ سلامت، تشخیص یا اطلاعات درمان خواسته نمی‌شود؛ توصیه نمی‌کنیم چنین اطلاعاتی را در بخش پیام بنویسید.</p>
<h2>هدف‌های پردازش</h2>
<p>داده‌های شخصی شما با این هدف‌ها پردازش می‌شوند: دریافت درخواست‌های تماس و نوبت، پاسخ به پرسش شما، آگاهی‌رسانی دربارهٔ برنامه‌ریزی نوبت و نگهداری سیاههٔ درخواست‌ها. داده‌های شما برای هدف‌های تبلیغاتی یا بازاریابی به کار نمی‌روند و با هدف‌های تجاری به اشخاص ثالث داده نمی‌شوند.</p>
<h2>مبنای قانونی و شیوهٔ گردآوری</h2>
<p>داده‌های شما به‌صورت الکترونیکی از راه فرم وب‌سایت گردآوری و بر پایهٔ مبناهای قانونی مادهٔ ۵ قانون KVKK پردازش می‌شوند؛ یعنی اینکه پردازش «مستقیماً با انعقاد یا اجرای یک قرارداد مرتبط است» و «برای منافع مشروع مسئول داده ضروری است، مشروط بر آنکه به حقوق و آزادی‌های بنیادین صاحب داده آسیب نرساند».</p>
<h2>انتقال</h2>
<p>داده‌های فرم نزد ارائه‌دهندهٔ خدمات میزبانی‌ای که وب‌سایت روی آن کار می‌کند نگهداری می‌شوند. بدون الزام قانونی به اشخاص ثالث در داخل یا خارج از کشور منتقل نمی‌گردند.</p>
<h2>مدت نگهداری</h2>
<p>داده‌های مربوط به درخواست تماس حداکثر تا یک سال پس از پایان درخواست نگهداری و سپس پاک یا ناشناس می‌شوند. اگر از دل یک درخواست پروندهٔ بیمار شکل گیرد، مدت‌های نگهداری مقررات سلامت اعمال می‌گردند.</p>
<h2>حقوق شما به‌عنوان صاحب داده</h2>
<p>بر پایهٔ مادهٔ ۱۱ قانون KVKK حق دارید: بدانید آیا داده‌های شخصی شما پردازش می‌شوند؛ اگر پردازش شده‌اند اطلاعات بخواهید؛ هدف پردازش و اینکه آیا در راستای همان هدف به کار رفته‌اند را بدانید؛ اشخاص ثالثی را که داده‌ها به آن‌ها داده شده بشناسید؛ در پردازش ناقص یا نادرست درخواست اصلاح کنید؛ درخواست پاک‌کردن یا نابودسازی کنید؛ بخواهید این اقدام‌ها به اشخاص ثالثی که داده‌ها به آن‌ها داده شده اطلاع داده شود؛ به نتیجه‌ای که تنها از تحلیل خودکار به زیان شما پدید آمده اعتراض کنید؛ و اگر از پردازش غیرقانونی زیانی به شما رسیده جبران خسارت بخواهید. درخواست‌های خود را می‌توانید به‌صورت کتبی به اطلاعات تماس بالا بفرستید؛ حداکثر ظرف ۳۰ روز پاسخ داده می‌شود.</p>
<p><em>این متن فارسی برای آگاهی‌رسانی است. در صورت اختلاف، نسخهٔ ترکی این متن ملاک است.</em></p>
<p><em>آخرین به‌روزرسانی: ۲۱.۰۹.۲۰۲۶</em></p>',
'متن روشنگری دربارهٔ داده‌های شخصی گردآوری‌شده از راه فرم تماس و نوبت‌گیری وب‌سایت dtmehmettas.com.tr.',
'متن روشنگری حفاظت از داده‌های شخصی | MSc. Dt. Mehmet Taş',
'FA' FROM pages WHERE link = 'kvkk-aydinlatma-metni';
